"""Check compact reference results generated by the saved regression calculation."""

import json
from datetime import date
from hashlib import md5
from pathlib import Path

import geopandas as gpd
import numpy as np
import pandas as pd
import pytest
from shapely import from_wkt
from shapely.geometry import box

from reuters_temperature_storms import WaveCells, WaveFootprints, WaveSeries

REFERENCE = json.loads(
    (Path(__file__).parent / "data" / "wave-footprints.json").read_text()
)


def reference_cells(case, day):
    """Construct canonical cells from the reference's coordinate/role examples.

    Args:
        case: Independent regression reference with cells and an optional span.
        day: Calendar date represented by all cells.

    Returns:
        WaveCells containing exact quarter-degree cells and paired seam halves.

    Examples:
        cells = reference_cells(REFERENCE["cases"][0], date(2024, 7, 15))

    Steps:
        1. Construct canonical cells from the reference's coordinate/role examples.
    """
    specs = list(case["cells"])
    if "longitude_span" in case:
        start, end, step, latitude, role = case["longitude_span"]
        specs.extend(
            (longitude, latitude, role)
            for longitude in np.arange(start, end + step / 2, step)
        )
    rows = []
    for longitude, latitude, role in specs:
        shapes = (
            (
                box(179.875, latitude - 0.125, 180, latitude + 0.125),
                box(-180, latitude - 0.125, -179.875, latitude + 0.125),
            )
            if longitude == 180
            else (
                box(
                    longitude - 0.125,
                    latitude - 0.125,
                    longitude + 0.125,
                    latitude + 0.125,
                ),
            )
        )
        rows.extend(
            {
                "longitude": float(longitude),
                "latitude": float(latitude),
                "days": np.nan if role == "fill" else 5.0,
                "grace_days": np.nan if role == "fill" else float(role == "grace"),
                "gap_filled": role == "fill",
                "geometry": shape,
                "date": pd.Timestamp(day),
            }
            for shape in shapes
        )
    frame = gpd.GeoDataFrame(rows, geometry="geometry", crs=4326)
    return WaveCells(frame)


@pytest.mark.parametrize("case", REFERENCE["cases"], ids=lambda case: case["name"])
@pytest.mark.parametrize("shuffle_seed", [0, 1])
def test_regression_reference_geometry_and_measurements(case, shuffle_seed):
    """Preserve reference geometry bytes, daily IDs and measurements.

    Args:
        case: Expected results generated by independent reference calculations.
        shuffle_seed: Input order permutation checked against the same reference.

    Returns:
        None; asserts exact IDs and geometry bytes for the compact scenes.
        World-width geometry is checked physically because raw union ordering
        differs across platforms; its bytes and IDs must remain stable when
        shuffled within the same runtime.

    Examples:
        Run ``pytest tests/test_wave_footprint_reference.py``.

    Steps:
        1. Preserve reference geometry bytes, daily IDs and measurements.
    """
    day = date.fromisoformat(REFERENCE["date"])
    cells = reference_cells(case, day)
    shuffled = WaveCells(cells.frame.sample(frac=1, random_state=shuffle_seed))
    frame = WaveFootprints.from_cells(
        shuffled, day, WaveSeries.parse(REFERENCE["series"])
    ).frame
    assert len(frame) == len(case["expected"])
    for (_, actual), expected in zip(frame.iterrows(), case["expected"], strict=True):
        if "storm_id" in expected:
            assert actual["storm_id"] == expected["storm_id"]
        else:
            baseline = WaveFootprints.from_cells(
                cells, day, WaveSeries.parse(REFERENCE["series"])
            ).frame.iloc[0]
            assert actual["storm_id"] == baseline["storm_id"]
            raw_hash = md5(
                f"{day.isoformat()} {actual['buffer_geometry'].wkt}".encode(),
                usedforsecurity=False,
            ).hexdigest()
            assert actual["storm_id"] == raw_hash
        assert actual["date"] == pd.Timestamp(day)
        for column in (
            "area_qualified",
            "area_grace",
            "area_gap_filled",
            "qualified_fraction",
        ):
            assert actual[column] == pytest.approx(
                expected[column], rel=1e-12, abs=1e-10
            )
        for column in ("geometry", "grace_geometry", "buffer_geometry"):
            geometry = actual[column]
            shape = expected[column]
            if shape is None:
                assert geometry is None
            elif "wkb_hex" in shape:
                assert geometry.wkb.hex() == shape["wkb_hex"]
            else:
                assert geometry.equals(from_wkt(shape["wkt"]))
                assert geometry.wkb == baseline[column].wkb
